import bisect
from collections import Counter, defaultdict
from typing import List, Tuple

import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Bounded character-Trie optimizer with exact tail local refinement."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional input frame and lightweight shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize one cell exactly as fillna('').astype(str) does for scoring."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the exact common-prefix length using bounded binary search."""
        limit = min(len(a), len(b))
        if limit == 0 or a[0] != b[0]:
            return 0
        lo, hi = 1, limit
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute ideal Trie reuse as LCPs of lexicographically adjacent strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested source-column groups contiguous without changing group order."""
        if not col_merge:
            return list(order)

        pos = {c: i for i, c in enumerate(order)}
        claimed = set()
        groups = {}
        for request in col_merge:
            group = [c for c in order if c in request and c not in claimed]
            if group:
                group.sort(key=pos.__getitem__)
                for c in group:
                    claimed.add(c)
                    groups[c] = group

        result, emitted = [], set()
        for c in order:
            if c in emitted:
                continue
            group = groups.get(c)
            if group is None:
                result.append(c)
                emitted.add(c)
            else:
                result.extend(group)
                emitted.update(group)
        return result

    @staticmethod
    def _strings(text, orders):
        """Serialize every row according to its row-specific source-column order."""
        return ["".join(text[r][j] for j in orders[r]) for r in range(len(orders))]

    def _global_candidates(self, text, columns, col_merge):
        """Construct two deterministic global orders ranked by repetition mass."""
        n, m = len(text), len(columns)
        stats = []
        for j in range(m):
            counts = Counter(text[r][j] for r in range(n))
            pair_mass = sum(len(v) * c * (c - 1) for v, c in counts.items())
            repeat_mass = sum(len(v) * (c - 1) for v, c in counts.items())
            stats.append((pair_mass, repeat_mass, len(counts)))

        rankings = [
            sorted(range(m), key=lambda j: (-stats[j][0], -stats[j][1], stats[j][2], j)),
            sorted(range(m), key=lambda j: (-stats[j][1], -stats[j][0], stats[j][2], j)),
        ]
        lookup = {c: j for j, c in enumerate(columns)}
        orders = []
        for ranking in rankings:
            merged = self._merge(columns, [columns[j] for j in ranking], col_merge)
            orders.append([lookup[c] for c in merged])
        return orders, rankings[0], stats

    def _conditional(self, text, columns, col_merge, global_order, stats):
        """Build bounded conditional prefix groups using length-weighted repetition."""
        n, m = len(text), len(columns)
        result = [None] * n
        useful = [j for j in global_order if stats[j][0] > 0][:min(20, m)]
        candidate_set = set(useful)
        max_depth = min(8, len(useful))
        node_limit = 384
        nodes = 0
        lookup = {c: j for j, c in enumerate(columns)}

        def complete(rows, prefix, remaining):
            """Assign each finished group a complete valid suffix permutation."""
            tail = [j for j in global_order if j in remaining]
            merged = self._merge(columns, [columns[j] for j in prefix + tail], col_merge)
            order = [lookup[c] for c in merged]
            for r in rows:
                result[r] = order[:]

        def visit(rows, remaining, prefix, depth):
            """Recursively split a group on its most reusable remaining field."""
            nonlocal nodes
            nodes += 1
            branchable = [j for j in remaining if j in candidate_set]
            if len(rows) < 2 or not branchable or depth >= max_depth or nodes > node_limit:
                complete(rows, prefix, remaining)
                return

            best_j, best_score, best_groups = -1, 0, None
            for j in branchable:
                groups = defaultdict(list)
                for r in rows:
                    groups[text[r][j]].append(r)
                score = sum(
                    len(value) * len(members) * (len(members) - 1)
                    for value, members in groups.items()
                    if len(members) > 1
                )
                if score > best_score or (
                    score == best_score and score > 0 and (best_j < 0 or j < best_j)
                ):
                    best_j, best_score, best_groups = j, score, groups

            if best_j < 0 or best_score <= 0:
                complete(rows, prefix, remaining)
                return

            rest = [j for j in remaining if j != best_j]
            groups = sorted(best_groups.values(), key=lambda g: (-len(g), min(g)))
            for group in groups:
                visit(group, rest, prefix + [best_j], depth + 1)

        visit(list(range(n)), list(range(m)), [], 0)
        fallback = list(global_order)
        for r in range(n):
            if result[r] is None:
                result[r] = fallback[:]
        return result

    def _refine(self, text, orders, strings, col_merge):
        """Perform one bounded exact Trie-neighbor tail-exchange sweep."""
        n, m = len(orders), self.num_cols
        if n < 2 or m < 2 or n > 20000 or m > 80:
            return orders, strings

        entries = sorted((strings[r], r) for r in range(n))

        def remove_delta(entry):
            """Return the exact reuse change caused by removing one sorted entry."""
            p = bisect.bisect_left(entries, entry)
            if p >= len(entries) or entries[p] != entry:
                return 0, p
            left = entries[p - 1][0] if p else None
            right = entries[p + 1][0] if p + 1 < len(entries) else None
            old = 0
            if left is not None:
                old += self._lcp(left, entry[0])
            if right is not None:
                old += self._lcp(entry[0], right)
            new = self._lcp(left, right) if left is not None and right is not None else 0
            return new - old, p

        def insert_delta(value):
            """Return the exact reuse change caused by inserting one sorted entry."""
            p = bisect.bisect_left(entries, value)
            left = entries[p - 1][0] if p else None
            right = entries[p][0] if p < len(entries) else None
            old = self._lcp(left, right) if left is not None and right is not None else 0
            new = 0
            if left is not None:
                new += self._lcp(left, value[0])
            if right is not None:
                new += self._lcp(value[0], right)
            return new - old

        opportunities = []
        for p, (value, r) in enumerate(entries):
            gain = 0
            if p:
                gain = max(gain, self._lcp(entries[p - 1][0], value))
            if p + 1 < n:
                gain = max(gain, self._lcp(value, entries[p + 1][0]))
            opportunities.append((gain, r))
        selected = [r for _, r in sorted(opportunities, key=lambda x: (-x[0], x[1]))[:192]]

        for r in selected:
            base = orders[r][:]
            blocks = []
            used = set()
            for j in base:
                if j in used:
                    continue
                block = [j]
                for request in col_merge or []:
                    if j in request:
                        block = [x for x in base if x in request]
                        break
                blocks.append(block)
                used.update(block)

            if len(blocks) < 2:
                continue
            blocks = blocks[:12]
            current = strings[r]
            best_order, best_string, best_gain = base, current, 0
            candidates = []

            for i in range(1, len(blocks)):
                candidates.append(blocks[i:] if i == 0 else [blocks[i]] + blocks[:i] + blocks[i + 1:])
            for i in range(1, len(blocks)):
                swapped = blocks[:]
                swapped[0], swapped[i] = swapped[i], swapped[0]
                candidates.append(swapped)

            for arrangement in candidates[:24]:
                proposal = [j for block in arrangement for j in block]
                value = "".join(text[r][j] for j in proposal)
                if value == current:
                    continue
                entry = (current, r)
                delta, pos = remove_delta(entry)
                entries.pop(pos)
                delta += insert_delta((value, r))
                bisect.insort(entries, (value, r))
                entries.pop(bisect.bisect_left(entries, (value, r)))
                bisect.insort(entries, entry)
                if delta > best_gain:
                    best_gain, best_order, best_string = delta, proposal, value

            if best_gain > 0:
                old_entry = (current, r)
                d, pos = remove_delta(old_entry)
                entries.pop(pos)
                bisect.insort(entries, (best_string, r))
                orders[r] = best_order
                strings[r] = best_string

        return orders, strings

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Construct bounded candidates, refine the best candidate, and return valid output."""
        self.df = df
        self.num_rows, self.num_cols = df.shape
        n, m = df.shape
        columns = list(df.columns)

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [[self._text(raw[r, j]) for j in range(m)] for r in range(n)]

        global_orders, global_order, stats = self._global_candidates(
            text, columns, col_merge
        )
        candidates = []

        for order in global_orders:
            row_orders = [order[:] for _ in range(n)]
            serial = self._strings(text, row_orders)
            candidates.append((self._reuse(serial), row_orders, serial))

        conditional = self._conditional(
            text, columns, col_merge, global_order, stats
        )
        conditional_serial = self._strings(text, conditional)
        candidates.append((self._reuse(conditional_serial), conditional, conditional_serial))

        _, best_orders, best_serial = max(candidates, key=lambda x: x[0])
        best_orders, best_serial = self._refine(
            text, best_orders, best_serial, col_merge
        )

        row_order = sorted(range(n), key=lambda r: best_serial[r])
        output = [[raw[r, j] for j in best_orders[r]] for r in row_order]
        orderings = [[columns[j] for j in best_orders[r]] for r in row_order]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings
